// Datos INVENTADOS: asigna pedidos (en pallets) a camiones, en orden y sin partir ninguno.
function asignar(pedidos, capacidad) {
  const camiones = [];
  let carga = 0;
  for (const p of pedidos) {
    if (p > capacidad) {
      throw new RangeError(`el pedido de ${p} pallets no entra en un camión de ${capacidad}`);
    }
    if (camiones.length === 0) camiones.push([]);
    if (carga + p > capacidad) {
      camiones.push([]);
      carga = 0;
    }
    camiones[camiones.length - 1].push(p);
    carga += p;
  }
  return camiones;
}

module.exports = { asignar };

const test = require('node:test');
const assert = require('node:assert/strict');
const { asignar } = require('./asignar.js');

const PEDIDOS = [8, 5, 9, 4, 7, 6, 3, 10, 2];
const suma = (camiones) => camiones.flat().reduce((a, b) => a + b, 0);

test('sin pedidos no hace falta ningún camión', () => {
  assert.deepEqual(asignar([], 12), []);
});

test('un pedido que justo completa el camión entra', () => {
  assert.deepEqual(asignar([6, 6], 12), [[6, 6]]);
});

test('un pedido que no entra abre otro camión', () => {
  assert.deepEqual(asignar([8, 5], 12), [[8], [5]]);
});

test('un pedido más grande que el camión es un error', () => {
  assert.throws(() => asignar([13], 12), RangeError);
});

test('REGRESIÓN: ningún pedido se pierde (el bug del continue)', () => {
  const camiones = asignar(PEDIDOS, 12);
  assert.equal(suma(camiones), suma([PEDIDOS]));
  assert.equal(camiones.length, 6);
});

